import json
import numbers


def key_mean_median(json_text):
    records = json.loads(json_text)
    # Collect numeric values per key
    values_by_key = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            if isinstance(value, bool) or not isinstance(value, numbers.Real):
                continue  # ignore missing/null/non-numeric values
            values_by_key.setdefault(key, []).append(value)

    result = {}
    for key, values in values_by_key.items():
        if not values:
            result[key] = {'mean': None, 'median': None}
            continue
        vals = sorted(values)
        n = len(vals)
        mean = sum(vals) / n
        if n % 2 == 1:
            median = float(vals[n // 2])
        else:
            median = (vals[n // 2 - 1] + vals[n // 2]) / 2.0
        result[key] = {'mean': mean, 'median': median}
    return result
```

