def merge_and_standardize(rows1, rows2):
    # Collect feature column names from each table (preserving order of appearance)
    cols1 = []
    for row in rows1:
        for k in row:
            if k != 'id' and k not in cols1:
                cols1.append(k)
    cols2 = []
    for row in rows2:
        for k in row:
            if k != 'id' and k not in cols2:
                cols2.append(k)

    # Collect all ids (preserving order for the join)
    all_ids = []
    for row in rows1 + rows2:
        if row['id'] not in all_ids:
            all_ids.append(row['id'])

    # Index rows by id
    table1 = {row['id']: row for row in rows1}
    table2 = {row['id']: row for row in rows2}

    # Compute mean and population std for table1's features, ignoring None
    stats = {}
    for col in cols1:
        vals = [row[col] for row in rows1 if row.get(col) is not None]
        n = len(vals)
        if n == 0:
            stats[col] = (None, None)
        else:
            mean = sum(vals) / n
            if n > 1:
                var = sum((v - mean) ** 2 for v in vals) / n
                std = var ** 0.5
            else:
                std = 0.0
            if std == 0:
                # constant column -> 0
                stats[col] = (mean, None)  # None std signals "output 0"
            else:
                stats[col] = (mean, std)

    # Build merged rows, sorted by id
    result = []
    for i in sorted(all_ids):
        merged = {'id': i}
        r1 = table1.get(i)
        r2 = table2.get(i)
        for col in cols1:
            v = r1.get(col) if r1 else None
            if v is None:
                merged[col] = None
            else:
                mean, std = stats[col]
                merged[col] = 0.0 if std is None else (v - mean) / std
        for col in cols2:
            merged[col] = (r2.get(col) if r2 else None)
        result.append(merged)

    return result
```

Example check:

```python
print(merge_and_standardize(
    [{'id': 1, 'a': 1.0}, {'id': 2, 'a': 3.0}],
    [{'id': 2, 'b': 5.0}, {'id': 3, 'b': 7.0}]
))
# [{'id': 1, 'a': -1.0, 'b': None}, {'id': 2, 'a': 1.0, 'b': 5.0},
#  {'id': 3, 'a': None, 'b': 7.0}]
```

Key points:
- **Outer join**: every id from either table appears in the output, sorted by id; missing entries become `None`.
- **Standardization**: only the first table's feature columns are standardized, using population standard deviation (`sum((v-mean)**2)/n`) computed over non-missing values; a constant (or single-value) column maps to `0.0`.
- **Missing values** in table 1 stay `None` (they're excluded from the mean/std computation but not filled in).

