import csv
import io


def fill_missing_with_column_mean(csv_text):
    """Parse CSV text and fill missing cells per column.

    - Numeric columns (every non-empty cell parses as a float) are returned
      as lists of floats, with empty cells replaced by the column mean.
    - Other columns are returned as lists of strings, with empty cells
      replaced by None.
    - A column with no values at all becomes all None.
    - Empty input yields an empty dict.
    """
    if csv_text is None or not csv_text.strip():
        return {}

    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]
    if not rows:
        return {}

    header = rows[0]
    ncols = len(header)

    # Normalize data rows: pad short rows, truncate long ones.
    data = []
    for row in rows[1:]:
        if len(row) < ncols:
            row = row + [''] * (ncols - len(row))
        elif len(row) > ncols:
            row = row[:ncols]
        data.append(row)

    result = {}
    for i, name in enumerate(header):
        column = [row[i] for row in data]
        present = [v for v in column if v != '']

        # Determine whether the column is numeric.
        numeric = True
        try:
            nums = [float(v) for v in present]
        except ValueError:
            numeric = False

        if numeric and nums:
            mean = sum(nums) / len(nums)
            result[name] = [
                float(v) if v != '' else mean for v in column
            ]
        else:
            result[name] = [v if v != '' else None for v in column]

    return result
```

