import json
import math


def numeric_correlation_from_json(json_text):
    """Compute the pairwise Pearson correlation matrix of the numeric columns
    in a JSON object mapping column names to equal-length lists of values.

    Raises ValueError if the text is not valid JSON or the data is empty.
    """
    # Parse the JSON; invalid JSON (or non-string input) -> ValueError
    try:
        data = json.loads(json_text)
    except (ValueError, TypeError) as exc:
        raise ValueError("Input is not valid JSON") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data is empty")

    # Validate structure and column lengths
    length = None
    for col, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column {col!r} does not hold a list of values")
        if length is None:
            length = len(values)
        elif len(values) != length:
            raise ValueError(f"Column {col!r} has a different length than the others")
    if length == 0:
        raise ValueError("Data is empty")

    # A column is numeric only if every value is an int or float (not bool)
    def is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    numeric_cols = [
        col for col, vals in data.items() if vals and all(is_number(v) for v in vals)
    ]
    if not numeric_cols:
        raise ValueError("Data is empty")

    n = length
    means = {}
    sds = {}
    for col in numeric_cols:
        vals = data[col]
        mean = sum(vals) / n
        var = sum((v - mean) ** 2 for v in vals) / n
        means[col] = mean
        sds[col] = math.sqrt(var)

    result = {col: {} for col in numeric_cols}
    for i, col1 in enumerate(numeric_cols):
        for col2 in numeric_cols[i:]:
            if col1 == col2:
                r = 1.0
            elif sds[col1] == 0 or sds[col2] == 0:
                # Zero variance makes Pearson correlation undefined; use 0.0
                r = 0.0
            else:
                cov = sum(
                    (v1 - means[col1]) * (v2 - means[col2])
                    for v1, v2 in zip(data[col1], data[col2])
                ) / n
                r = max(-1.0, min(1.0, cov / (sds[col1] * sds[col2])))
            result[col1][col2] = r
            result[col2][col1] = r

    return result
```

### Example usage

```python
print(numeric_correlation_from_json('{"a": [1, 2, 3], "b": [2, 4, 7]}'))
# {'a': {'a': 1.0, 'b': 0.993399267798783}, 'b': {'a': 0.993399267798783, 'b': 1.0}}

print(numeric_correlation_from_json('{"a": [1, 2, 3], "s": ["x", "y", "z"]}'))
# {'a': {'a': 1.0}}   -- non-numeric column "s" is ignored

numeric_correlation_from_json('not json')
# ValueError: Input is not valid JSON

numeric_correlation_from_json('{"a": []}')
# ValueError: Data is empty
```

### Key details

- **Parsing errors**: `json.loads` raises `JSONDecodeError` (a subclass of `ValueError`), but it's caught and re-raised with a clear message; `TypeError` (non-string input) is handled too.
- **Numeric columns**: a column is numeric only if *all* of its values are `int` or `float`. Booleans are explicitly excluded (in Python, `bool` is a subclass of `int`).
- **Empty data**: raises `ValueError` when the JSON is an empty object, all lists are empty, or no numeric columns remain after filtering.
- **Symmetry**: each pair is computed once and stored in both `(col1, col2)` and `(col2, col1)`. The diagonal is set to exactly `1.0`, and results are clamped to `[-1, 1]` to guard against tiny floating-point excursions.
- **Zero variance**: correlation is mathematically undefined when a column is constant; the convention `0.0` is used so the matrix is still returned.

