import csv
import io


def _parse_number(s):
    """Try to parse a CSV field as a number, handling thousands separators."""
    s = s.strip().replace(',', '')
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]

    if not rows or len(rows) < 2:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    header = rows[0]
    data_rows = rows[1:]
    n_cols = len(header)

    # Parse every column; keep only columns where ALL values are numeric.
    columns = {name: [] for name in header}
    for row in data_rows:
        for i in range(n_cols):
            value = row[i] if i < len(row) else ''
            columns[header[i]].append(value)

    numeric_columns = {}
    for name, values in columns.items():
        parsed = [_parse_number(v) for v in values]
        if parsed and all(p is not None for p in parsed):
            numeric_columns[name] = parsed

    # Means
    means = {name: sum(vals) / len(vals) for name, vals in numeric_columns.items()}

    # Sample standard deviations (0.0 when a column has fewer than 2 values)
    std_devs = {}
    for name, vals in numeric_columns.items():
        if len(vals) < 2:
            std_devs[name] = 0.0
        else:
            m = means[name]
            std_devs[name] = (
                sum((x - m) ** 2 for x in vals) / (len(vals) - 1)
            ) ** 0.5

    # One-way ANOVA across numeric columns (treated as groups)
    f_value = None
    if len(numeric_columns) >= 2:
        all_vals = [v for vals in numeric_columns.values() for v in vals]
        grand_mean = sum(all_vals) / len(all_vals)
        k = len(numeric_columns)

        ss_between = sum(
            len(vals) * (means[name] - grand_mean) ** 2
            for name, vals in numeric_columns.items()
        )
        ss_within = sum(
            (x - means[name]) ** 2
            for name, vals in numeric_columns.items()
            for x in vals
        )

        ms_between = ss_between / (k - 1)
        ms_within = ss_within / (len(all_vals) - k)

        if ms_within != 0:
            f_value = ms_between / ms_within
        elif ms_between != 0:
            f_value = float('inf')

    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}
```

Example usage:

```python
result = summarize_numeric_csv('A,B\n1,4\n2,5\n3,6\n')
# {'means': {'A': 2.0, 'B': 5.0}, 'std_devs': {'A': 1.0, 'B': 1.0}, 'f_value': 13.5}
```

A few notes on the implementation:

- **Thousands separators** are handled by stripping commas from fields before numeric conversion; since the `csv` module handles quoting, a field like `"1,000"` arrives as the string `1,000`.
- **Non-numeric columns** are detected by attempting to parse *every* value in a column; if any fails (including empty fields), the whole column is excluded from the output.
- **Sample standard deviation** uses `n - 1` in the denominator; a column with only one value gets `0.0`.
- **ANOVA**: the F statistic is `MS_between / MS_within`, where between-group degrees of freedom is `k - 1` (number of groups) and within-group is `N - k` (total observations minus groups). If there's zero within-group variance, `f_value` is `None` (or `inf` if the between-group variance is nonzero) to avoid division by zero.

